export type PlatformMessageKey = keyof typeof PLATFORM_MESSAGES.he;
export function translatePlatform(language: PlatformLanguage, key: PlatformMessageKey): string {
  return PLATFORM_MESSAGES[language][key] ?? PLATFORM_MESSAGES.he[key];
}
export function platformDirection(language: PlatformLanguage): 'rtl' | 'ltr' {
  return language === 'he' ? 'rtl' : 'ltr';
}
